processes.command_line:
"C:\Users\ASUS\.cache\codex-runtimes\codex-primary-runtime\dependencies\native\powershell\pwsh.exe" -NoProfile -Command "try { [Console]::OutputEncoding=[System.Text.Encoding]::UTF8 } catch {}
$ErrorActionPreference='Stop'
$root = Join-Path $PWD 'deployment/ownership_forensics'
New-Item -ItemType Directory -Force -Path $root | Out-Null
$statePath = Join-Path $PWD 'deployment/public_demo_state.json'
Copy-Item -LiteralPath $statePath -Destination (Join-Path $root 'CURRENT_PUBLIC_DEMO_STATE_PRE_FIX.json') -Force
$state = Get-Content -LiteralPath $statePath -Raw | ConvertFrom-Json
$snapshotTime = [DateTimeOffset]::UtcNow
function Redact-CommandLine([string]$value) {
  if (-not $value) { return $value }
  $redacted = $value -replace '(?i)(authorization|api[_-]?key|token|secret|password)(\s*[=:]\s*)([^\s\"'']+)', '$1$2[REDACTED]'
  $redacted = $redacted -replace '(?i)Bearer\s+[^\s\"'']+', 'Bearer [REDACTED]'
  return $redacted
}
$processes = @(Get-CimInstance Win32_Process | ForEach-Object {
  $gp = Get-Process -Id ([int]$_.ProcessId) -ErrorAction SilentlyContinue
  [ordered]@{
    process_id = [int]$_.ProcessId
    parent_process_id = [int]$_.ParentProcessId
    creation_date_raw = if ($_.CreationDate) { $_.CreationDate.ToString('o') } else { $null }
    creation_time_utc = if ($_.CreationDate) { ([DateTimeOffset]$_.CreationDate).ToUniversalTime().ToString('o') } else { $null }
    get_process_start_time_utc = if ($gp) { try { $gp.StartTime.ToUniversalTime().ToString('o') } catch { $null } } else { $null }
    name = [string]$_.Name
    executable_path = [string]$_.ExecutablePath
    command_line = Redact-CommandLine ([string]$_.CommandLine)
  }
})
$listeners = @(Get-NetTCPConnection -State Listen -ErrorAction SilentlyContinue | ForEach-Object {
  [ordered]@{ local_address=[string]$_.LocalAddress; local_port=[int]$_.LocalPort; owning_process=[int]$_.OwningProcess }
})
$componentPids = @($state.api_pid,$state.worker_pid,$state.cloudflared_pid) + @($state.api_process_tree.pid) + @($state.worker_process_tree.pid) + @($state.cloudflared_process_tree.pid)
$componentPids = @($componentPids | Where-Object { $_ } | ForEach-Object { [int]$_ } | Sort-Object -Unique)
$payload = [ordered]@{
  captured_at_utc = $snapshotTime.ToString('o')
  classification = 'PRE_FIX_READ_ONLY_FORENSICS'
  state_path = [IO.Path]::GetFullPath($statePath)
  deployment_started_at = [string]$state.started_at
  tunnel_url = [string]$state.tunnel_origin
  api_port = [int]$state.api_port
  recorded_component_pids = $componentPids
  state_process_trees_trust = 'UNTRUSTED_DERIVED_STATE'
  processes = $processes
  listening_ports = $listeners
  component_port_mapping = @($listeners | Where-Object { $_.owning_process -in $componentPids -or $_.local_port -eq [int]$state.api_port })
}
$payload | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $root 'PRE_FIX_PROCESS_SNAPSHOT.json') -Encoding utf8
$hash = (Get-FileHash -Algorithm SHA256 -LiteralPath (Join-Path $root 'CURRENT_PUBLIC_DEMO_STATE_PRE_FIX.json')).Hash.ToLowerInvariant()
[ordered]@{ snapshot=(Join-Path $root 'PRE_FIX_PROCESS_SNAPSHOT.json'); state_copy=(Join-Path $root 'CURRENT_PUBLIC_DEMO_STATE_PRE_FIX.json'); state_sha256=$hash; process_count=$processes.Count; listener_count=$listeners.Count } | ConvertTo-Json"
